export function isSpellingRequired(word: string): boolean {
  const entry = VOCAB_TIERS[word.toLowerCase()];
  if (!entry) return true;
  return entry.t < 2;
}

export function getUnfamiliarHint(word: string): string | null {
  const e = UNFAMILIAR_MEANINGS[word.toLowerCase()];
  if (!e) return null;
  return "熟义：" + e.c + "｜生义：" + e.u;
}

export function getPolysemyHint(word: string): string | null {
  return POLYSEMY[word.toLowerCase()] || null;
}